package com.brightloop.quotation;
import com.brightloop.catalog.Customer;import com.brightloop.discount.Discount;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="quotations") public class Quotation{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="quotation_number",nullable=false,unique=true,length=40) String quotationNumber;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id",nullable=false) Customer customer;@Column(nullable=false,length=20) String status="DRAFT";@Column(name="created_on",nullable=false) LocalDate createdOn;@Column(name="expires_on",nullable=false) LocalDate expiresOn;@Column(name="payment_terms") String paymentTerms;@Column(columnDefinition="TEXT") String notes;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="discount_id") Discount discount;@Column(nullable=false,precision=14,scale=2) BigDecimal subtotal;@Column(name="discount_amount",nullable=false,precision=14,scale=2) BigDecimal discountAmount;@Column(name="tax_amount",nullable=false,precision=14,scale=2) BigDecimal taxAmount;@Column(name="grand_total",nullable=false,precision=14,scale=2) BigDecimal grandTotal;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) Instant updatedAt=Instant.now();@OneToMany(mappedBy="quotation",cascade=CascadeType.ALL,orphanRemoval=true) List<QuotationLine> lines=new ArrayList<>();
 protected Quotation(){}public Quotation(String n,Customer c,LocalDate created,LocalDate expires,String terms,String notes,Discount d,BigDecimal subtotal,BigDecimal disc,BigDecimal tax,BigDecimal total){quotationNumber=n;customer=c;createdOn=created;expiresOn=expires;paymentTerms=terms;this.notes=notes;discount=d;this.subtotal=subtotal;discountAmount=disc;taxAmount=tax;grandTotal=total;}
 public void addLine(QuotationLine line){lines.add(line);}public List<QuotationLine> getLines(){return lines;}public Long getId(){return id;}public String getQuotationNumber(){return quotationNumber;}public Customer getCustomer(){return customer;}public String getStatus(){return status;}public LocalDate getCreatedOn(){return createdOn;}public LocalDate getExpiresOn(){return expiresOn;}public String getPaymentTerms(){return paymentTerms;}public String getNotes(){return notes;}public Discount getDiscount(){return discount;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getDiscountAmount(){return discountAmount;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getGrandTotal(){return grandTotal;}public void markSent(){if(!"DRAFT".equals(status))throw new IllegalStateException("Only drafts can be sent");status="SENT";}public void confirm(){if(!"SENT".equals(status)&&!"DRAFT".equals(status))throw new IllegalStateException("Quotation cannot be confirmed from "+status);if(LocalDate.now().isAfter(expiresOn))throw new IllegalStateException("Quotation has expired");status="CONFIRMED";}public void converted(){if(!"CONFIRMED".equals(status))throw new IllegalStateException("Only confirmed quotations can be converted");status="CONVERTED";}
 public void revise(Customer c,LocalDate created,LocalDate expires,String terms,String notes,Discount discount,BigDecimal subtotal,BigDecimal discountAmount,BigDecimal tax,BigDecimal total){customer=c;createdOn=created;expiresOn=expires;paymentTerms=terms;this.notes=notes;this.discount=discount;this.subtotal=subtotal;this.discountAmount=discountAmount;taxAmount=tax;grandTotal=total;}
}
